# Generate TypeScript output
out_items = []
for i, item in enumerate(all_items):
    word, syllables, stressed_idx, pos, explanation = item
    sentence = f"The candidate was asked to analyze the word '{word}' in the English examination."
    out_items.append({
        "id": f"sg-{i+1}",
        "word": word,
        "syllables": syllables,
        "stressedIndex": stressed_idx,
        "partOfSpeech": pos,
        "sentenceExample": sentence,
        "explanation": explanation
    })

